mapper.select:
SELECT d.device_no AS deviceNo,
r.curve_type AS curveType,
r.sample_time AS sampleTime,
r.reading_value AS value
FROM curve_reading r
JOIN device d ON d.id = r.device_id
WHERE r.sample_time >= #{startUtc}
AND r.sample_time < #{endUtc}


    AND d.device_no IN

        #{deviceNo}




    AND r.curve_type = #{curveType}


    AND r.reading_value >= #{minKwh}


    AND r.reading_value <= #{maxKwh}


ORDER BY r.sample_time, r.device_id, r.curve_type
LIMIT #{limit} OFFSET #{offset}
